let actx=null;
function audioCtx(){if(!actx)actx=new(window.AudioContext||window.webkitAudioContext)();if(actx.state==='suspended')actx.resume();return actx}
function beep(freq,dur,type,vol,delay){try{let ctx=audioCtx(),t=ctx.currentTime+(delay||0),osc=ctx.createOscillator(),gain=ctx.createGain();osc.type=type||'square';osc.frequency.setValueAtTime(freq,t);gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(vol||.1,t+.005);gain.gain.exponentialRampToValueAtTime(.0001,t+(dur||.08));osc.connect(gain);gain.connect(ctx.destination);osc.start(t);osc.stop(t+(dur||.08)+.02)}catch(e){}}
const sfx={
 click:()=>beep(720,.045,'square',.07),
 select:()=>beep(880,.03,'square',.05),
 connect:()=>{beep(660,.05,'square',.09);beep(990,.07,'square',.07,.05)},
 error:()=>{beep(180,.09,'square',.11);beep(140,.13,'square',.11,.09)},
 type:()=>beep(1150+Math.random()*250,.02,'square',.03),
 success:()=>{beep(523,.08,'square',.09);beep(659,.08,'square',.09,.09);beep(784,.14,'square',.1,.18)},
 shake:()=>beep(380,.04,'square',.06),
 packOpen:()=>{beep(300,.07,'sawtooth',.08);beep(600,.08,'square',.09,.07);beep(900,.14,'square',.1,.15)},
 alarm:()=>{beep(220,.16,'sawtooth',.12);beep(220,.16,'sawtooth',.12,.24)},
 bossHit:()=>beep(150,.05,'square',.07),
 victory:()=>[523,659,784,1046].forEach((f,i)=>beep(f,.13,'square',.09,i*.09)),
 gameOver:()=>[392,349,294,220].forEach((f,i)=>beep(f,.2,'sawtooth',.09,i*.15))
};
document.addEventListener('click',e=>{if(e.target.closest('button'))sfx.click()});
const chapters=[{title:'[1라운드] 식량 생산 기반',desc:'목표: 밀 3개 생산',key:'wheat',goal:3,label:'📦 1라운드 보상 팩',stars:[{type:'time',sec:90},{type:'hpAtClear',n:8,hint:'밀을 노동자에게 연결해 체력을 회복시키세요.'}],cards:[['unit',100,420,'▣ 추가 노동자 1명이 배정되었습니다.'],['land',360,420,'▣ 추가 경작지가 배정되었습니다.'],['seed',620,420,'▣ 씨앗 5개가 추가 지급되었습니다.']],story:[['아리아','밀 3개 생산을 확인했습니다. 제1캠프의 최소 식량 생산성이 기준치를 통과했습니다.'],['시스템 기록','2라운드 기능 승인: 회사 상납 및 크레딧 배급 요청.'],['아리아','식량을 본사에 상납하면 크레딧을 얻습니다. 크레딧으로 필요한 신규 노드를 배급 요청할 수 있습니다.']]},{title:'[2라운드] 회사 상납',desc:'목표: 크레딧 30 획득',creditGoal:30,label:'📦 2라운드 보상 팩',stars:[{type:'time',sec:60},{type:'resourceAtClear',key:'wheat',min:3,hint:'땅을 2곳 이상 운영해 밀을 병렬로 생산하세요.'}],cards:[['autoMiner',100,650,'▣ 자동 작업 장비가 승인되었습니다.'],['gravityOre',600,650,'▣ 중력석 광맥 채굴 권한이 승인되었습니다.'],['mill',900,650,'▣ 제분기 설치가 승인되었습니다.']],story:[['아리아','복원 사업 지원금 목표를 달성했습니다. 이번 성과를 근거로 하트웰 복원국이 캠프1 지하 방공호 심층부의 신규 채굴권을 승인했습니다. 정찰 도중 고에너지 결정체 — 인턴들 사이에서는 \'중력석\'이라 불리는 광물이 다량 확인되었습니다.','gravityFound'],['아리아','주의하십시오. 중력석 원석은 정제되기 전까지 불안정합니다. 채굴 중 주변 시설에 위험 반경이 발생하므로, 인접 배치 시 손상에 유의하시기 바랍니다. 이는 3단계 실습 평가 항목에 포함됩니다.','gravityHazard'],['아리아','3라운드 실습 목표는 중력석 원석 3개 채굴입니다. 노동력을 광맥에 연결해 원석을 확보하십시오. 정제·조립 설비는 이후 단계에서 지급됩니다.','gravityMission']]},{title:'[3라운드] 중력석 채굴 사업',desc:'목표: 중력석 원석 3개 채굴',key:'gravityStone',goal:3,label:'📦 3라운드 보상 팩',stars:[{type:'time',sec:60},{type:'maxErosion',v:.5,hint:'광맥의 위험 반경(150px) 밖에 시설을 배치하세요.'}],cards:[['gravityPlant',100,1150,'▣ 중력 정제소 설치가 승인되었습니다.'],['gravityForge',600,1150,'▣ 중력 코어 조립소가 지급되었습니다.'],['seedFarm',900,1150,'▣ 씨앗 재배기 설치가 승인되었습니다.']],story:[['아리아','중력석 원석 채굴 목표를 달성했습니다. 하트웰 복원국이 원석 정제·조립 설비 운용을 승인했습니다.','gravityRefine'],['아리아','4라운드 실습 목표는 씨앗 5개 보유입니다. 여분의 씨앗을 비축해 순환 체계를 준비하십시오.','seedStockMission']]},{title:'[4라운드] 씨앗 순환 체계',desc:'목표: 씨앗 5개 보유',key:'seed',goal:5,label:'📦 4라운드 보상 팩',stars:[{type:'time',sec:60},{type:'noPurchase',hint:'씨앗 재배기로 밀을 씨앗으로 순환시키세요.'}],cards:[['unit',100,1275,'▣ 추가 노동자 1명이 배정되었습니다.']],story:[['아리아','씨앗 비축 목표를 달성했습니다. 잉여 밀을 씨앗으로 재순환할 수 있는 재배 설비가 지급되었습니다.','seedCycle'],['아리아','5라운드 실습 목표는 정제 중력석 3개 생산입니다. 정제소를 연결해 안정화된 에너지원을 확보하십시오.','gravityRefineMission']]},{title:'[5라운드] 중력 코어 개발',desc:'목표: 정제 중력석 3개 생산',key:'gravityCore',goal:3,label:'📦 5라운드 보상 팩',stars:[{type:'time',sec:150},{type:'time',sec:60,hint:'과부하를 광맥에 연결하면 채굴이 빨라집니다.'}],cards:[['lumberCamp',100,1400,'▣ 벌목장 운영 권한이 승인되었습니다.'],['sawmill',600,1400,'▣ 제재소 설치가 승인되었습니다.'],['oven',900,1400,'▣ 화덕 설치가 승인되었습니다.']],story:[['아리아','정제 중력석 생산 목표를 달성했습니다. 안정화된 에너지원 확보를 근거로, 캠프 방어선 구축에 필요한 목재 조달 사업이 승인되었습니다.','campMaterials'],['아리아','6라운드 실습 목표는 판자 3개 생산입니다. 벌목장과 제재소를 연결해 방어선 자재를 확보하십시오.','campMaterialsMission']]},{title:'[6라운드] 벌목 및 제재 시설',desc:'목표: 판자 3개 생산',key:'plank',goal:3,label:'📦 6라운드 보상 팩',stars:[{type:'time',sec:120},{conds:[{type:'time',sec:60},{type:'maxWorkers',n:1}],hint:'과부하를 쓰면 노동자 없이도 생산량이 늘어납니다.'}],cards:[['stoneSource',100,1650,'▣ 암석 자원지 채굴 권한이 승인되었습니다.'],['ironSource',600,1650,'▣ 철광석 자원지 채굴 권한이 승인되었습니다.'],['mix',900,1650,'▣ 조합 시설(Mix)이 지급되었습니다.']],story:[['아리아','판자 생산 목표를 달성했습니다. 하트웰 복원국은 채석·제련 설비와 함께, 불안정한 에너지장으로부터 시설을 보호할 방어선 구축 사업을 승인했습니다.','campDefense'],['아리아','2073년 제1차 카오스 당시의 배급 폭동을 상기하십시오. 이번 방어선은 외부 위협뿐 아니라 캠프 내부의 소요 가능성에도 대비합니다.','chaosEcho'],['아리아','7라운드 실습 목표는 곡괭이 2개 보유입니다. Mix에서 판자와 돌을 조합해 곡괭이를 제작하십시오.','miningMission'],['아리아','참고로 채굴 장비는 사용할수록 마모될 수 있습니다. 지금은 단순 보유 자원으로 집계되지만, 향후 운용 단계에서는 소모품으로 취급될 수 있으니 기억해 두시기 바랍니다.']]},{title:'[7라운드] 채굴 효율화',desc:'목표: 곡괭이 2개 보유',key:'pickaxe',goal:2,label:'📦 7라운드 보상 팩',stars:[{type:'time',sec:120},{type:'time',sec:55,hint:'목재와 돌을 동시에 생산하면 더 빨라집니다.'}],cards:[['autoMiner',100,1900,'▣ 추가 자동 채굴기가 배정되었습니다.']],story:[['아리아','곡괭이 채굴 효율화 목표를 달성했습니다. 곡괭이를 채굴 시설에 연결하면 작업 속도가 크게 향상됩니다.','miningBoost'],['아리아','8라운드 실습 목표는 빵 3개 보유입니다. 제분기와 화덕을 연결해 비상 식량을 비축하십시오.','emergencyMission']]},{title:'[8라운드] 비상 대비',desc:'목표: 빵 3개 보유',key:'bread',goal:3,label:'📦 8라운드 보상 팩',stars:[{type:'time',sec:240},{type:'keepMin',key:'seed',min:5,hint:'씨앗 재배기 비율을 조절해 씨앗을 5개 이상으로 유지하세요.'}],cards:[['unit',100,2150,'▣ 최종 결전을 앞두고 추가 인력이 배정되었습니다.']],story:[['아리아','비상 식량 비축 목표를 달성했습니다. 최종 결전을 앞두고 추가 인력이 배정되었습니다.','finalPrep'],['아리아','9라운드 실습 목표는 중력 코어 발전기 1개 보유입니다. 중력 코어 조립소를 가동해 안정적인 에너지원을 확보하십시오.','energyMission']]},{title:'[9라운드] 에너지 발전 체계',desc:'목표: 중력 코어 발전기 1개 보유',key:'gravityReactor',goal:1,label:'📦 9라운드 보상 팩',stars:[{type:'time',sec:120},{type:'time',sec:50,hint:'곡괭이와 과부하를 함께 연결하면 더 빨라집니다.'}],cards:[['unit',100,2400,'▣ 최종 결전을 앞두고 추가 인력이 배정되었습니다.']],story:[['아리아','에너지 발전 체계 가동 목표를 달성했습니다. 캠프 전역에 안정적인 동력이 공급되기 시작했습니다.','energyOnline'],['아리아','10라운드 실습 목표는 검 2자루 보유입니다. 채석, 제련, 조합까지 전체 생산망을 완성하십시오.','campDefenseMission']]},{title:'[10라운드] 캠프 방어선 구축',desc:'목표: 검 2개 보유',key:'sword',goal:2,label:'📦 10라운드 보상 팩',stars:[{type:'time',sec:90},{type:'time',sec:30,hint:'Mix의 입력을 분리해 철과 돌을 병렬로 공급하세요.'}],cards:[['stabilizer',100,2650,'▣ 중력장 안정기가 지급되었습니다. 위기 노드의 두 번째 입력 포트에 연결하면 침식 구역을 억제할 수 있습니다.']],boss:true,story:[['아리아','예기치 못한 사태가 발생했습니다 — 배급 갈등이 폭동으로 번지고 있습니다. 2073년과 같은 참사를 막으려면 보유한 모든 동력을 연결해 즉시 대응하십시오.','secondChaos']]},{title:'[11라운드] 선택의 기로',desc:'목표: 위기를 진압하십시오.',finalChoice:true,stars:[{type:'time',sec:60},{type:'bossBurst',sec:3,hint:'연산기로 공격력 16 이상을 만들어 한 번에 진압하세요.'}],label:'📦 11라운드 보상 팩',cards:[['scrapYard',100,2900,'▣ 폐허 매장지 채굴 권한이 승인되었습니다.'],['charcoalKiln',600,2900,'▣ 숯가마 설치가 승인되었습니다.'],['steelForge',900,2900,'▣ 제련소 설치가 승인되었습니다.']],story:[['아리아','1차 평가가 마무리되었습니다. 하지만 캠프의 재건 작업은 계속됩니다. 하트웰 복원국은 캠프 심층부 폐허 지대에서 고자재급 금속을 회수하는 사업을 승인했습니다.'],['아리아','주의하십시오 — 폐허에서의 채굴은 곡괭이를 마모시킵니다. 지속적인 채굴을 위해서는 판자와 돌로 곡괭이를 계속 공급하십시오.'],['아리아','12라운드 실습 목표는 강철 3개 생산입니다. 고철과 숯을 제련소에 연결하십시오.']]},{title:'[12라운드] 폐허 고철 회수 & 제련',desc:'목표: 강철 3개 생산',key:'steel',goal:3,label:'📦 12라운드 보상 팩',stars:[{type:'time',sec:300},{type:'keepMin',key:'pickaxe',min:1,hint:'곡괭이 공급망(Mix)을 계속 가동해 곡괭이가 끊기지 않게 하세요.'}],cards:[['unit',100,3150,'▣ 추가 노동자 1명이 배정되었습니다.'],['warehouseBuilder',600,3150,'▣ 저장고 건설반이 지급되었습니다.']],boss:true,bossKind:'raiders',bossPos:{x:1700,y:3150},story:[['아리아','강철 확보 목표를 달성했습니다. 재건 물자의 장기 보관을 위해, 하트웰 복원국은 저장시설 건설 사업을 승인했습니다.'],['아리아','13라운드 실습 목표는 저장고 3기 건설입니다. 강철과 판자를 저장고 건설반에 연결하십시오.'],['아리아','예기치 못한 사태가 발생했습니다 — 쌓여가는 강철과 비축 물자를 노린 폐허 도적떼가 캠프를 습격하고 있습니다. Mix에서 강철과 목재를 조합하면 강철검을 제작할 수 있습니다. 보유한 모든 화력을 연결해 즉시 방어하십시오.']]},{title:'[13라운드] 저장고 건설',desc:'목표: 저장고 3기 건설',key:'storage',goal:3,label:'📦 13라운드 보상 팩',requireNoBoss:true,stars:[{type:'time',sec:360},{type:'bossBurst',sec:5,hint:'강철검·검·노동자의 공격력을 덧셈기로 합산해 한 번에 진압하세요.'}],cards:[['unit',100,3400,'▣ 재건 공로를 인정받아 추가 인력이 배정되었습니다.'],['unit',600,3400,'▣ 재건 공로를 인정받아 추가 인력이 배정되었습니다.']],complete:'1구역 재건 2차 사이클(자원 심화 편)이 완료되었습니다 — 제련과 물자 보관 체계까지 갖추었고, 이를 노린 폐허 도적떼의 습격까지 격퇴했습니다. 이후 계획은 본사 심의를 거쳐 별도 공지됩니다.'}];
