const historyImages=Object.fromEntries(['hartwell','intern','mission','board','node','wire','reward'].map(k=>[k,`assets/prologue/${k}.png`]));
const finalChoiceDialogue=[['아리아','위기는 진압되었습니다. 1차 실습 평가가 이 시점에서 마무리됩니다.','endingSetup'],['아리아','수고하셨습니다, 인턴 님. 지금까지의 기록은 평가 자료로 자동 제출되었습니다.']];
const intro=[['아리아','2074년, 레비아 하트웰은 “감시와 통제 없이는 인간은 서로를 죽인다”고 선언하며 하트웰 복원국을 세웠습니다.','hartwell'],['아리아','이후 배급과 치안, 정보망은 모두 중앙 통제 아래 놓였습니다.','hartwell'],['아리아','안녕하세요, 인턴 님.','intern'],['아리아','저는 하트웰 복원국 교육 담당 AI, 아리아입니다.','intern'],['아리아','지금부터 진행되는 과정은 「제1캠프 복원 시뮬레이션 실습」이며, 신규 인턴이 반드시 이수해야 하는 필수 교육입니다.','intern'],['아리아','실습 결과는 인턴 평가 자료로 자동 기록되니 참고하시기 바랍니다.','intern'],['아리아','실습 목표는 간단합니다.','mission'],['아리아','노드로 노동력과 자원을 연결해 복원 사업의 기초 운영 절차를 체득하는 것입니다.','mission'],['아리아','지금부터의 모든 조작, 생산량, 위기 대응 기록은 상부의 실제 복원 결정에 참고 자료로 제출됩니다.','mission'],['아리아','그럼 오리엔테이션을 계속하겠습니다.','mission']];
const boardGuide=[['아리아','[실습 브리핑 1/4] 지금 화면은 복원 보드, 즉 인턴 실습용 작업 화면입니다.','board'],['아리아','각 노드는 작업반, 자원 구역, 보유 물자 또는 복원 시설을 의미합니다.','board'],['아리아','교육 과정에 따라 하나씩 안내하겠습니다.','board'],['아리아','[실습 브리핑 2/4] 노드는 드래그해서 이동할 수 있고, 빈 공간을 드래그하면 여러 노드를 한 번에 선택할 수 있습니다.','node'],['아리아','가운데 버튼을 누른 채 드래그하면 화면이 이동합니다.','node'],['아리아','실습 중 자유롭게 연습해보시기 바랍니다.','node'],['아리아','[실습 브리핑 3/4] 출력 포트에서 호환되는 입력 포트까지 드래그하면 공급망이 연결됩니다.','wire'],['아리아','진행바가 가득 차면 물자 생산 또는 시설 작업이 완료 처리됩니다.','wire'],['아리아','이는 평가 항목의 핵심 절차이니 반드시 숙지하시기 바랍니다.','wire'],['아리아','[실습 브리핑 4/4] 목표를 달성하면 하트웰이 복원 물자 팩을 지급합니다.','reward'],['아리아','일부 단계에서는 캠프 전체를 위협하는 복합 위기가 발생하니 대응 절차도 함께 평가됩니다.','reward'],['아리아','오리엔테이션을 마칩니다 — 실습을 시작하세요.','reward']];
let G=null,mode='new',slot=-1,timer=null,lastTickAt=performance.now(),drag=null,link=null,armed=null,box=null,panDrag=null,clip=[],clipW=[],pasteN=0,dialogue=null,toastT=null,pendingDelete=-1,packMode='reward',packDone=null,touchPoints=new Map(),pinch=null,confirmAction=null,pendingResultContinue=null;
const fresh=()=>({nodes:[],wires:[],chapter:0,cleared:false,counter:0,main:null,credits:0,starterOpened:false,pan:{x:0,y:0,z:1},paused:false,gameOver:false,selected:[],selectedW:[],selectedR:[],round:{t:0,failed:[],firstHit:null,bossDefeatT:null,creditsAtStart:0},stars:{},starMilestones:{},upgrades:{},bought:{},crLog:{}});
const upgradeDefs={hp:{name:'노동력 체력',vals:[0,.3,.6,1],cost:[40,90,200],unlock:[1,1,8]},food:{name:'섭취 효율',vals:[0,1,2,3],cost:[30,80,180],unlock:[1,1,8]},tribute:{name:'상납 단가',vals:[0,.1,.2,.35],cost:[50,120,250],unlock:[2,2,8]},proc:{name:'가공 속도',vals:[0,.2,.45,.8],cost:[60,140,280],unlock:[3,3,8]}};
const up=k=>upgradeDefs[k].vals[G.upgrades?.[k]||0];
const facilityBasePrice={unit:30,land:25};
function priceFor(kind){let base=facilityBasePrice[kind];if(base===undefined)return null;return Math.round(base*Math.pow(1.25,G.bought?.[kind]||0))}
function logCr(amount){if(!amount)return;G.crLog=G.crLog||{};G.crLog[G.chapter]=(G.crLog[G.chapter]||0)+amount}
function uid(){return'n'+(G.counter++)}function spawn(kind,x,y,extra={}){let n={id:uid(),kind,x:Math.round(x/20)*20,y:Math.round(y/20)*20,count:0,progress:0,processing:false,recipe:-1,erosion:0,radius:D[kind].radius||0,hp:D[kind].hp||0,copy:false,...extra};G.nodes.push(n);return n}function node(id){return G.nodes.find(n=>n.id===id)}function def(n){return D[n.kind]}function saveKey(i){return'nodecraft_html_slot_'+i}
function show(id){['titleScreen','slotScreen','loadingScreen','playScreen'].forEach(x=>$('#'+x).classList.toggle('hidden',x!==id))}function overlay(id,on){$('#'+id).classList.toggle('hidden',!on)}
function fade(fn){$('#fade').classList.add('on');setTimeout(()=>{fn();requestAnimationFrame(()=>$('#fade').classList.remove('on'))},360)}
function openSlots(isNew){mode=isNew?'new':'continue';$('#slotTitle').textContent=isNew?'새 게임 슬롯 선택':'이어하기 슬롯 선택';renderSlots();fade(()=>show('slotScreen'))}
function renderSlots(){let h='';for(let i=0;i<4;i++){let s=loadSlot(i),stars=s?Object.values(s.stars||{}).reduce((a,b)=>a+b,0):0,badge=stars>=39?' · 우수':'';h+=`<button class="slot" data-slot="${i}" ${!s&&mode==='continue'?'disabled':''}><h3>슬롯 ${i+1}</h3>${s?`<p>${chapters[Math.min(s.chapter,chapters.length-1)]?.title||'평가 완료'}</p><p>노드 ${s.nodes.length}개 · ★ ${stars} / 39${badge} · ${s.saved||''}</p><span class="delete" data-delete="${i}">삭제</span>`:`<p>비어 있음</p><p>${mode==='new'?'새로운 게임을 시작합니다.':'저장된 게임이 없습니다.'}</p>`}</button>`}$('#slots').innerHTML=h}
function loadSlot(i){try{return JSON.parse(localStorage.getItem(saveKey(i)))}catch{return null}}function checkpoint(){if(slot<0||!G)return;G.saved=new Date().toLocaleString('ko-KR');localStorage.setItem(saveKey(slot),JSON.stringify(G));$('#saveState').textContent='저장 완료';setTimeout(()=>$('#saveState').textContent='자동 저장',900)}
function enter(i){slot=i;show('loadingScreen');setTimeout(()=>{if(mode==='new'){G=fresh();let u=spawn('unit',100,150);G.main=u.id;spawn('land',350,150)}else G=loadSlot(i);if(node(G.main))node(G.main).locked=false;startPlay(mode==='new')},1250)}
function startPlay(isNew){show('playScreen');G.paused=false;G.gameOver=false;G.credits??=0;G.round??={t:0,failed:[],firstHit:null,bossDefeatT:null,creditsAtStart:G.credits||0};G.round.creditsAtStart??=G.credits||0;G.stars??={};G.starMilestones??={};G.upgrades??={};G.bought??={};G.crLog??={};renderAll();focusMain();clearInterval(timer);timer=setInterval(tick,1000);let tutorial=()=>{checkpointRoundStart();if(!localStorage.getItem('nodecraft_tutorial'))overlay('tutorial',true);else $('#firstHint').classList.remove('hidden')};if(isNew)playDialogue(intro,()=>playDialogue(boardGuide,()=>openStarterPack(tutorial)))}
function renderAll(){renderMissions();renderNodes();renderWires();renderZones();renderFields();renderShop();applyView();$('#chapterBadge').textContent=G.chapter<chapters.length?`복원 단계 ${String(G.chapter+1).padStart(2,'0')}`:'평가 완료';$('#firstHint').classList.toggle('hidden',G.wires.length>0);updatePauseIndicator()}
function formatRoundTime(sec){let m=Math.floor(sec/60),s=sec%60;return `${m}:${String(s).padStart(2,'0')} 남음`}
function starLinesHtml(c,i){if(!c.stars||i!==G.chapter||G.cleared)return'';return c.stars.map((star,si)=>{let failed=G.round.failed.includes(si),timeCond=starConds(star).find(x=>x.type==='time'),burstCond=starConds(star).find(x=>x.type==='bossBurst'),timing='';if(!failed&&timeCond){let remain=timeCond.sec-G.round.t;timing=`<span class="${remain<=10?'star-warn':''}">⏱ ${remain>=0?formatRoundTime(remain):'초과'}</span>`}else if(!failed&&burstCond&&G.round.firstHit!=null){let remain=burstCond.sec-(G.round.t-G.round.firstHit);timing=`<span class="${remain<=2?'star-warn':''}">⏱ ${Math.max(0,remain)}초 남음</span>`}return `<div class="star-cond ${failed?'star-failed':''}">${'★'.repeat(si+2)} ${starConditionLabel(star)} ${timing}</div>`}).join('')}
const tut3Steps=[{title:'일시정지 후 노드 정리',text:'Space를 누르면 시뮬레이션이 일시정지됩니다. 멈춘 동안에도 노드 이동 · 연결 · 삭제는 그대로 할 수 있으니, 배치가 복잡해지면 멈추고 정리하세요.',cta:'Space를 눌러 일시정지해 보세요',ctaTouch:'오른쪽 위 Ⅱ 버튼을 눌러 일시정지해 보세요',key:true},{el:'#requisitionBtn',label:'배급 요청 열기',title:'배급 요청',text:'크레딧으로 씨앗 · 땅 · 노동자 같은 기본 노드를 지급받습니다. 생산 라인을 늘리고 싶을 때 사용하세요.',cta:'배급 요청 버튼을 눌러 보세요'},{el:'#functionBtn',label:'기능 노드 열기',title:'기능 노드',text:'분배기 · 과부하 · 덧셈기 같은 특수 노드를 요청합니다. 각 노드에 마우스를 올리면 기능 설명을 볼 수 있어요.',cta:'기능 노드 버튼을 눌러 보세요'},{el:'#researchBtn',label:'연구 승인 열기',title:'영구 업그레이드',text:'연구 승인에서 노동력 체력 · 섭취 효율 · 상납 단가 · 가공 속도를 영구히 강화합니다. 한 번 올린 단계는 이후 라운드에도 계속 유지됩니다.',cta:'연구 승인 버튼을 눌러 보세요'}];
