const guides=[{key:'tut1',chapter:0,steps:tut1Steps,ready:()=>!G.cleared&&!!guideNode()&&G.nodes.some(n=>def(n).type==='Source'&&n.staffed),onStart:()=>focusNode(guideNode()),doneTitle:'일시정지 안내 완료',doneText:'필요할 때 노드를 클릭해 라인을 멈추고 재개하세요. 1라운드 목표를 계속 진행하세요.'},{key:'tut3',chapter:2,steps:tut3Steps,ready:()=>true,doneTitle:'운영 안내 완료',doneText:'필요한 도구는 모두 확인했습니다. 3라운드 목표를 진행하세요.'}];
function activeGuide(){return G?guides.find(x=>G[x.key]!=null&&!G[x.key+'Done'])||null:null}
function tut3Active(){return activeGuide()?.key==='tut3'}
function endGuide(gd){G[gd.key]=null;G[gd.key+'Done']=true}
function renderGuideCard(){let card=$('#tutorCard');if(!card||card.classList.contains('tc-complete'))return;let gd=activeGuide();if(!gd){card.classList.add('hidden');return}let steps=gd.steps,i=G[gd.key],s=steps[i],key=gd.key+i+'|'+isTouch();if(card.dataset.step===key&&!card.classList.contains('hidden'))return;card.dataset.step=key;$('#tcStep').textContent=`${String(i+1).padStart(2,'0')} / ${String(steps.length).padStart(2,'0')}`;$('#tcBar').innerHTML=steps.map((_,k)=>`<i class="${k<i?'done':k===i?'cur':''}"></i>`).join('');$('#tcKey').classList.toggle('hidden',!s.key||isTouch());$('#tcTitle').textContent=s.title;$('#tcText').textContent=s.text;$('#tcCta').textContent=isTouch()&&s.ctaTouch?s.ctaTouch:s.cta;card.classList.remove('hidden','tc-swap');void card.offsetWidth;card.classList.add('tc-swap')}
function advanceGuide(){let gd=activeGuide();if(!gd)return;G[gd.key]++;sfx.success();if(G[gd.key]>=gd.steps.length){endGuide(gd);let card=$('#tutorCard');card.classList.add('tc-complete');card.classList.remove('tc-swap');void card.offsetWidth;card.classList.add('tc-swap');$('#tcStep').textContent='COMPLETE';$('#tcBar').innerHTML=gd.steps.map(()=>'<i class="done"></i>').join('');$('#tcKey').classList.add('hidden');$('#tcTitle').textContent=gd.doneTitle;$('#tcText').textContent=gd.doneText;$('#tcCta').textContent=G.paused?'Space를 눌러 시뮬레이션을 재개하세요':'';setTimeout(()=>{card.classList.remove('tc-complete');card.classList.add('hidden')},5000)}checkpoint();renderGuideCard();updateGuideArrow()}
function tickGuides(){if(!G||$('#playScreen').classList.contains('hidden'))return;let gd=activeGuide();if(gd&&G.chapter!==gd.chapter){endGuide(gd);gd=null}if(!gd&&!document.querySelector('.overlay:not(.hidden)')){let next=guides.find(x=>x.chapter===G.chapter&&G[x.key]==null&&!G[x.key+'Done']&&x.ready());if(next){G[next.key]=0;next.onStart?.();checkpoint();gd=next}}if(gd&&gd.steps[G[gd.key]]?.done?.())advanceGuide();renderGuideCard()}
function guideTarget(){if(!G||G.gameOver)return null;let gd=activeGuide();if(gd){let s=gd.steps[G[gd.key]];if(s.node){let wn=guideNode();return wn?{el:$(`.node[data-node="${wn.id}"]`),dir:'up',text:s.label}:null}if(s.el)return{el:$(s.el),dir:'up',text:s.label};return isTouch()?{el:$('#pauseBtn'),dir:'up',text:'일시정지'}:{el:$('#tutorCard'),dir:'up',text:'Space 키를 눌러 보세요',tag:'PRESS ▸'}}let c=chapters[G.chapter];if(G.chapter===0&&G.cleared&&c&&!c.finalChoice)return{el:$('#packBtn'),dir:'left',text:'1라운드 보상 팩 받기'};if(G.chapter===1&&!G.cleared&&!G.tributeGuided&&Object.keys(tributeRates).some(k=>resourceTotal(k)>0))return{el:$('#tributeBtn'),dir:'up',text:'자원 상납하기'};return null}
function updateGuideArrow(){let a=$('#guideArrow');if(!a)return;document.querySelectorAll('.guide-target').forEach(b=>b.classList.remove('guide-target'));let t=guideTarget(),el=t&&t.el;if(!el||el.classList.contains('hidden')||$('#playScreen').classList.contains('hidden')){a.classList.add('hidden');return}let pr=$('#playScreen').getBoundingClientRect(),r=el.getBoundingClientRect(),dir=t.dir,aside=$('aside').getBoundingClientRect();if(dir==='left'&&(r.width===0||aside.right<=pr.left+4)){el=$('#sidebarToggle');r=el.getBoundingClientRect();dir='up'}if(r.width===0){a.classList.add('hidden');return}if(!el.classList.contains('node'))el.classList.add('guide-target');let x=dir==='up'?r.left+r.width/2-pr.left:Math.max(r.right,aside.right)-pr.left+6,y=dir==='up'?r.bottom-pr.top+6:r.top+r.height/2-pr.top;if(a.dataset.dir!==dir||a.classList.contains('hidden')){a.dataset.dir=dir;a.classList.remove('hidden');a.classList.remove('ga-enter');void a.offsetWidth;a.classList.add('ga-enter')}$('#guideArrowText').textContent=t.text;a.querySelector('.ga-label small').textContent=t.tag||'CLICK ▸';let lw=a.querySelector('.ga-label').offsetWidth/2+8;a.dataset.align=dir!=='up'?'':x<lw?'start':x>pr.width-lw?'end':'';a.classList.toggle('ga-compact',dir==='left'&&x+260>pr.width);a.style.left=x+'px';a.style.top=y+'px'}
addEventListener('resize',()=>{if(G)updateGuideArrow()});setInterval(()=>{if(G){tickGuides();updateGuideArrow();if(!$('#playScreen').classList.contains('hidden'))updatePauseIndicator()}},400);
function renderMissions(){$('#missions').style.counterReset=`ms ${G.chapter}`;$('#missions').innerHTML=chapters.map((c,i)=>({c,i})).filter(({i})=>i>=G.chapter&&i<=G.chapter+1).map(({c,i})=>{let v=c.finalChoice?0:c.creditGoal?(i===G.chapter?Math.max(0,(G.credits||0)-(G.round?.creditsAtStart||0)):0):(c.key?resourceTotal(c.key):0),goal=c.finalChoice?1:(c.creditGoal||c.goal),done=i===G.chapter&&G.cleared;return`<div class="mission ${i>G.chapter?'locked':''} ${done?'done':''}"><h3>${c.title}</h3><p>${c.desc}</p><div class="progress"><i style="width:${Math.min(100,v/goal*100)}%"></i></div><div class="progress-row"><span>${done?'✓ 완료':c.finalChoice?'대응 중':'진행 중'}</span><span>${c.finalChoice?'':v+' / '+goal}</span></div>${starLinesHtml(c,i)}</div>`}).join('');let c=chapters[G.chapter];$('#packBtn').classList.toggle('hidden',!c||!G.cleared||!!c.finalChoice);if(c)$('#packBtn').textContent=c.label;$('#credits').textContent=`CR ${G.credits||0}`;$('#tributeBtn').classList.toggle('hidden',G.chapter<1);$('#requisitionBtn').classList.toggle('hidden',G.chapter<1);$('#functionBtn').classList.toggle('hidden',G.chapter<1);$('#researchBtn').classList.toggle('hidden',G.chapter<1);updateGuideArrow()}
function portHtml(types,dir){return types.map((t,i)=>`<i class="port ${dir}" data-port="${i}" data-dir="${dir}" data-shape="${portShape[t]||'circle'}" style="--port:${C[t]||C.Splitter};top:${42+i*27}px" title="${dir==='in'?'입력':'출력'} · ${typeLabel[t]||t}"></i>`).join('')}
function nodeStatus(n){let d=def(n);if(d.locked||n.locked||n.suspended)return null;if(d.type==='Unit'){if(n.hp>0&&n.hp<=maxHp(n)*.3)return'체력 위험';return null}if(d.type==='Source'){let ins=incoming(n.id).map(x=>resolveNode(x.n.id)).filter(Boolean),workers=ins.filter(rn=>def(rn).type==='Unit'&&rn.hp>0);if(!workers.length)return'노동력 필요';if(d.seedKey&&!ins.find(rn=>def(rn).key===d.seedKey&&rn.count>0))return'씨앗 부족';return null}if(['Processor','Logic'].includes(d.type)){if(n.processing)return null;let inputs={};for(let q of incoming(n.id)){let r=resolveResource(q.n.id);if(r)inputs[def(r).key]=r}if(!d.recipes.some(rec=>Object.entries(rec.in).every(([k,v])=>inputs[k]&&inputs[k].count>=v)))return'재료 부족';return null}return null}
let nodeTap=null;function canSuspend(n){let d=def(n);return!!n&&!(d.locked||n.locked)&&!['Boss','Resource','Equipment'].includes(d.type)}
function toggleSuspend(list){list=list.filter(canSuspend);if(!list.length)return;let on=list.some(n=>!n.suspended);for(let n of list){n.suspended=on;if(on)n.staffed=false}toast(list.length>1?`노드 ${list.length}개 ${on?'작동 일시정지':'작동 재개'}`:`${def(list[0]).title} ${on?'작동 일시정지':'작동 재개'}`);sfx.shake();renderAll();checkpoint()}
function renderNodes(){$('#nodes').innerHTML=G.nodes.map(n=>{let d=def(n),sel=G.selected.includes(n.id),locked=d.locked||n.locked,bar=d.time?Math.min(100,n.progress/d.time*100):0,label=d.type==='Unit'?`HP ${Math.max(0,n.hp)} / ${maxHp(n)}`:d.type==='Resource'||d.type==='Equipment'?`× ${n.count}`:d.type==='Boss'?`HP ${Math.max(0,n.hp)} / ${d.hp}`:power(n.id)>0&&['Combinator','Splitter'].includes(d.type)?`Power ${power(n.id)}`:'',st=nodeStatus(n),foodVal=d.food?(d.heal||1)+up('food'):0;return`<article class="node ${sel?'selected':''} ${locked?'locked':''} ${n.suspended?'suspended':''}" data-node="${n.id}" data-kind="${n.kind}" data-type="${d.type}" style="left:${n.x}px;top:${n.y}px;--node:${C[d.type]};filter:brightness(${1-n.erosion*.48})"><div class="node-head"><small>${typeLabel[d.type]||d.type}</small></div>${n.suspended?'<span class="halt-mark" aria-label="일시정지됨"><span class="hm-icon"><i></i><i></i></span><b>PAUSED</b></span>':''}<div class="node-body"><span class="node-icon-big" aria-hidden="true">${iconHtml(n.kind)}</span><b class="node-name">${d.title}</b></div>${portHtml(d.ins,'in')}${portHtml(d.outs,'out')}<b class="node-count">${label}</b>${foodVal?`<span class="food-badge" title="섭취 시 노동자 체력 회복량">❤ +${foodVal}</span>`:''}${st?`<span class="status-badge" title="${st}">⚠ ${st}</span>`:''}${n.erosion>0?`<span class="erosion"><i style="width:${n.erosion*100}%"></i></span>`:''}<span class="node-progress"><i style="width:${bar}%"></i></span></article>`}).join('');updateMobileActions()}
function updateProgressBars(now){if(G){let lead=Math.max(0,Math.min(1,(now-lastTickAt)/1000));for(let n of G.nodes){let d=def(n);if(!d.time)continue;let shown=n.progress+(n.processing&&!G.paused&&!n.suspended?lead*(1-n.erosion):0),fill=$(`.node[data-node="${n.id}"] .node-progress i`);if(fill)fill.style.width=Math.min(100,shown/d.time*100)+'%'}}requestAnimationFrame(updateProgressBars)}
function endpoint(n,dir,i){let el=$(`.node[data-node="${n.id}"] .port.${dir}[data-port="${i}"]`),vr=$('#viewport').getBoundingClientRect(),r=el.getBoundingClientRect();return{x:(r.left+r.width/2-vr.left-G.pan.x)/G.pan.z,y:(r.top+r.height/2-vr.top-G.pan.y)/G.pan.z}}
function path(points){if(points.length===2){let[a,b]=points,dx=Math.max(60,Math.abs(b.x-a.x)*.45);return`M${a.x},${a.y} C${a.x+dx},${a.y} ${b.x-dx},${b.y} ${b.x},${b.y}`}return points.map((p,i)=>(i?'L':'M')+p.x+','+p.y).join(' ')}
function renderWires(){let h='';for(let i=0;i<G.wires.length;i++){let w=G.wires[i],a=node(w.from),b=node(w.to);if(!a||!b)continue;let pts=[endpoint(a,'out',w.fp),...(w.points||[]),endpoint(b,'in',w.tp)],col=C[def(a).outs[w.fp]]||C.Splitter;h+=`<path class="wire ${G.selectedW.includes(i)?'selected':''} ${a.suspended?'halted':''}" data-wire="${i}" d="${path(pts)}" stroke="${col}"/>`}if(link){let a=endpoint(node(link.from),'out',link.port);h+=`<path class="wire preview ${link.valid?'valid':'invalid'}" d="${path([a,{x:link.x,y:link.y}])}" stroke="${C[def(node(link.from)).outs[link.port]]||'#aaa'}"/>`}$('#wires').innerHTML=h;$('#wires').querySelectorAll('.wire:not(.preview)').forEach(p=>{p.onclick=e=>selectWire(+p.dataset.wire,e);p.ondblclick=e=>addReroute(+p.dataset.wire,e);p.oncontextmenu=e=>{e.preventDefault();disconnectWire(+p.dataset.wire)};p.onpointerdown=e=>{if(e.pointerType!=='touch')return;let wi=+p.dataset.wire,timer=setTimeout(()=>disconnectWire(wi),550),cancel=()=>{clearTimeout(timer);p.removeEventListener('pointerup',cancel);p.removeEventListener('pointermove',cancel);p.removeEventListener('pointerleave',cancel)};p.addEventListener('pointerup',cancel);p.addEventListener('pointermove',cancel);p.addEventListener('pointerleave',cancel)}});renderReroutes();updateMobileActions()}
function updateMobileActions(){$('#mobileActions')?.classList.toggle('hidden',!(G.selected.length||G.selectedW.length))}
function disconnectWire(i){if(!G.wires[i])return;G.wires.splice(i,1);G.selectedW=[];renderWires();renderNodes();toast('연결을 해제했습니다.','silent');sfx.shake()}
function renderReroutes(){let h='';G.wires.forEach((w,wi)=>(w.points||[]).forEach((p,pi)=>h+=`<i class="reroute ${G.selectedR.some(r=>r[0]===wi&&r[1]===pi)?'selected':''}" data-w="${wi}" data-p="${pi}" style="left:${p.x}px;top:${p.y}px"></i>`));$('#reroutes').innerHTML=h;$$('.reroute').forEach(el=>el.onpointerdown=e=>{e.stopPropagation();let wi=+el.dataset.w,pi=+el.dataset.p;G.selectedR=e.shiftKey?[...G.selectedR,[wi,pi]]:[[wi,pi]];drag={reroute:[wi,pi]};el.setPointerCapture(e.pointerId)})}
function compatible(a,fp,b,tp){let A=def(a),B=def(b),ot=A.outs[fp],it=B.ins[tp];if(A.type==='Splitter'||B.type==='Splitter')return true;if(a.kind==='if5'||b.kind==='if5')return true;if(ot!==it)return false;if(A.type==='Unit'&&!['Source','Processor','Logic','Combinator','Boss'].includes(B.type))return false;if(A.type==='Source'&&(B.type!=='Resource'||A.key!==B.key))return false;if(A.type==='Resource'&&B.type==='Source')return B.seedKey===A.key||B.boostKey===A.key;if(A.type==='Resource'&&B.type==='Unit')return !!A.food;if(A.type==='Resource'&&!['Processor','Logic'].includes(B.type))return false;if(['Processor','Logic'].includes(A.type)&&!['Resource','Equipment'].includes(B.type))return false;if(A.type==='Buff'&&!['Source','Processor','Boss'].includes(B.type))return false;if(['Combinator','Equipment'].includes(A.type)&&!['Combinator','Boss'].includes(B.type))return false;return a.id!==b.id}
function connect(from,fp,to,tp){let A=def(from);G.wires=G.wires.filter(w=>!(w.to===to.id&&w.tp===tp)&&!((A.type!=='Resource')&&w.from===from.id&&w.fp===fp));G.wires.push({from:from.id,fp,to:to.id,tp,points:[]});burstPort(to.id,tp,'#4caf50');$('#firstHint').classList.add('hidden');toast(`${A.title} → ${def(to).title} 연결`);renderWires()}
function selectWire(i,e){if(e.altKey){disconnectWire(i);return}G.selectedW=e.shiftKey?(G.selectedW.includes(i)?G.selectedW.filter(x=>x!==i):[...G.selectedW,i]):[i];renderWires()}
function addReroute(i,e){let p=screenToWorld(e.clientX,e.clientY);G.wires[i].points.push({x:Math.round(p.x/20)*20,y:Math.round(p.y/20)*20});G.wires[i].points.sort((a,b)=>a.x-b.x);renderWires()}
function screenToWorld(x,y){let r=$('#viewport').getBoundingClientRect();return{x:(x-r.left-G.pan.x)/G.pan.z,y:(y-r.top-G.pan.y)/G.pan.z}}
function updatePortHighlight(){$$('.port.in').forEach(p=>{let el=p.closest('.node'),n=el&&node(el.dataset.node);if(!link||!n){p.classList.remove('port-ok','port-no');return}let ok=compatible(node(link.from),link.port,n,+p.dataset.port);p.classList.toggle('port-ok',ok);p.classList.toggle('port-no',!ok)})}
function portAtPoint(clientX,clientY){let hit=document.elementFromPoint(clientX,clientY)?.closest('.port.in');if(!hit)return null;let el=hit.closest('.node');return el?{n:node(el.dataset.node),tp:+hit.dataset.port}:null}
function nearestCompatiblePort(clientX,clientY,fromNode,fromPort,maxDist=36){let best=null,bestDist=maxDist;$$('.port.in').forEach(p=>{let el=p.closest('.node'),n=el&&node(el.dataset.node);if(!n)return;let tp=+p.dataset.port;if(!compatible(fromNode,fromPort,n,tp))return;let r=p.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,d=Math.hypot(clientX-cx,clientY-cy);if(d<bestDist){bestDist=d;best={n,tp}}});return best}
function applyView(){$('#world').style.transform=`translate(${G.pan.x}px,${G.pan.y}px) scale(${G.pan.z})`;$('#zoomLabel').textContent=Math.round(G.pan.z*100)+'%'}
function renderZones(){let hz=G.nodes.filter(n=>def(n).hazard).map(n=>{let r=n.radius||def(n).radius||0;return`<div class="hazard-zone${n.staffed?' active':''}" style="left:${n.x+87-r}px;top:${n.y+56-r}px;width:${r*2}px;height:${r*2}px"><span>${n.staffed?'⚠ 위험 반경 · 채굴 중':'위험 반경 · 대기'}</span></div>`}).join('');$('#zones').innerHTML=hz+G.nodes.filter(n=>def(n).type==='Boss').map(n=>`<div class="zone" style="left:${n.x+87}px;top:${n.y+56}px;width:${n.radius*2}px;height:${n.radius*2}px"></div>`).join('')}
const fieldSourceCfgs=[{kind:'land',label:'🌾 밀 밭',color:'#ffd600',needsSeed:true},{kind:'gravityOre',label:'⛏ 중력석 광산',color:'#8b5cf6'},{kind:'stoneSource',label:'⛏ 암석 채석장',color:'#9ca3af'},{kind:'ironSource',label:'🔩 철광 채굴장',color:'#64748b'},{kind:'lumberCamp',label:'🪓 벌목장',color:'#65a30d'},{kind:'scrapYard',label:'🏚 폐허 매장지',color:'#78716c'}];
const fieldProcessCfgs=[{kind:'gravityPlant',label:'🏭 중력석 제련시설',color:'#14b8a6'},{kind:'gravityForge',label:'⚡ 중력석 코어 생산시설',color:'#ff8c1a'},{kind:'mill',label:'⚙ 제분소',color:'#f59e0b'},{kind:'oven',label:'🔥 제빵소',color:'#dc2626'},{kind:'sawmill',label:'🪚 제재소',color:'#a16207'},{kind:'seedFarm',label:'🌱 씨앗 재배소',color:'#22c55e'},{kind:'mix',label:'🔧 조합 시설',color:'#0ea5e9'},{kind:'charcoalKiln',label:'🔥 숯가마',color:'#57534e'},{kind:'steelForge',label:'⚒ 제련소',color:'#71717a'},{kind:'warehouseBuilder',label:'🏗 저장고 건설반',color:'#0891b2'}];
function fieldGroups(){let out=[];for(let cfg of fieldSourceCfgs)for(let n of G.nodes.filter(n=>n.kind===cfg.kind)){let ins=incoming(n.id),worker=ins.find(x=>x.w.tp===0&&def(resolveNode(x.n.id)||x.n).type==='Unit')?.n,seed=cfg.needsSeed?ins.find(x=>x.w.tp===1&&def(resolveNode(x.n.id)||x.n).key==='seed')?.n:null,output=sourceOutput(n.id,D[cfg.kind].key);if(worker&&(!cfg.needsSeed||seed)&&output)out.push({label:cfg.label,color:cfg.color,nodes:cfg.needsSeed?[worker,seed,n,output]:[worker,n,output]})}for(let cfg of fieldProcessCfgs)for(let n of G.nodes.filter(n=>n.kind===cfg.kind)){let incNodes=incoming(n.id).map(x=>resolveNode(x.n.id)||x.n);for(let rec of D[cfg.kind].recipes){let inputsOk=Object.keys(rec.in).every(k=>incNodes.some(x=>def(x).key===k)),output=sourceOutput(n.id,rec.out.key);if(inputsOk&&output){out.push({label:cfg.label,color:cfg.color,nodes:[n,output]});break}}}return out}
function renderFields(){$('#fields').innerHTML=fieldGroups().map(({label,color,nodes:ns})=>{let minX=Math.min(...ns.map(n=>n.x))-22,minY=Math.min(...ns.map(n=>n.y))-38,maxX=Math.max(...ns.map(n=>n.x+174))+22,maxY=Math.max(...ns.map(n=>n.y+140))+22;return`<div class="field${fieldDrag?' dragging':''}" data-nodes="${ns.map(n=>n.id).join(',')}" style="left:${minX}px;top:${minY}px;width:${maxX-minX}px;height:${maxY-minY}px;--field-color:${color};--field-bg:${color}1f;--field-border:${color}b3"><span class="field-label">${label}</span></div>`}).join('')}
let fieldDrag=null;
$('#fields').addEventListener('pointerdown',e=>{let el=e.target.closest('.field');if(!el||e.button!==0)return;e.nodeCraftHandled=true;e.preventDefault();e.stopPropagation();let ids=el.dataset.nodes.split(',');fieldDrag={ids};el.classList.add('dragging');el.setPointerCapture(e.pointerId);if(!e.shiftKey){G.selected=ids.slice()}else{G.selected=[...new Set([...G.selected,...ids])]}$$('.node').forEach(x=>x.classList.toggle('selected',G.selected.includes(x.dataset.node)));drag={sx:e.clientX,sy:e.clientY,starts:ids.map(id=>{let n=node(id);return{id,x:n.x,y:n.y}})}});
function incoming(id){return G.wires.filter(w=>w.to===id).map(w=>({w,n:node(w.from)})).filter(x=>x.n&&!x.n.suspended)}function resources(k){return G.nodes.filter(n=>['Resource','Equipment'].includes(def(n).type)&&def(n).key===k)}function findResource(k){return resources(k)[0]}function resourceTotal(k){return resources(k).reduce((sum,n)=>sum+(n.count||0),0)}function sourceOutput(id,k){for(let w of G.wires){if(w.from!==id)continue;let target=node(w.to);if(target&&def(target).key===k)return target}return null}
function resolveResource(id,seen=new Set){if(seen.has(id))return null;seen.add(id);let n=node(id);if(!n)return null;if(['Resource','Equipment'].includes(def(n).type))return n;if(def(n).type==='Splitter'){let i=incoming(id)[0];return i?resolveResource(i.n.id,seen):null}if(n.kind==='if5'){let i=incoming(id)[0];if(!i)return null;let r=resolveResource(i.n.id,seen);return r&&r.count>=5?r:null}return null}
function resolveNode(id,seen=new Set){if(seen.has(id))return null;seen.add(id);let n=node(id);if(!n)return null;if(def(n).type==='Splitter'){let i=incoming(id)[0];return i?resolveNode(i.n.id,seen):null}if(n.kind==='if5'){let i=incoming(id)[0];if(!i)return null;let r=resolveNode(i.n.id,seen);if(!r)return null;if(['Resource','Equipment'].includes(def(r).type)&&r.count<5)return null;return r}return n}
function resolveNodeInfo(id,seen=new Set){if(seen.has(id))return null;seen.add(id);let n=node(id);if(!n)return null;if(def(n).type==='Splitter'){let i=incoming(id)[0];if(!i)return null;let r=resolveNodeInfo(i.n.id,seen);return r?{node:r.node,splitter:true}:null}if(n.kind==='if5'){let i=incoming(id)[0];if(!i)return null;let r=resolveNodeInfo(i.n.id,seen);if(!r)return null;if(['Resource','Equipment'].includes(def(r.node).type)&&r.node.count<5)return null;return r}return{node:n,splitter:false}}
function power(id,seen=new Set){if(seen.has(id))return 0;seen.add(id);let n=node(id);if(!n)return 0;let d=def(n),mul=1-n.erosion;if(d.type==='Unit')return Math.round((d.attack||0)*mul);if(d.type==='Equipment')return n.count?Math.round(d.equip*mul):0;if(d.type==='Splitter'){let q=incoming(id)[0];return q?power(q.n.id,seen):0}if(d.type!=='Combinator')return 0;let vals=incoming(id).map(x=>power(x.n.id,new Set(seen))),v=0;if(d.op==='constant')v=3;else if(d.op==='add')v=vals.reduce((a,b)=>a+b,0);else if(d.op==='multiply')v=vals.length?vals.reduce((a,b)=>a*b,1):0;else if(d.op==='multiply2')v=(vals[0]||0)*2;else if(d.op==='if')v=(vals[0]||0)>=5?vals[0]:0;else v=vals[0]||0;return Math.round(v*(d.op==='portal'?1:mul))}
function tick(){if(!G||G.paused||G.gameOver)return;lastTickAt=performance.now();for(let b of G.nodes.filter(n=>def(n).type==='Boss')){let stab=incoming(b.id).filter(x=>x.n.kind==='stabilizer').reduce((s,x)=>s+(def(x.n).stabilize||0),0);b.radius=Math.max(80,Math.min(500,b.radius+1.5-stab));let q=incoming(b.id).find(x=>x.w.tp===0),hit=q?power(q.n.id):0;if(hit){b.hp-=hit;burstAt(b.x+87,b.y+55,'#ff5252',12);sfx.bossHit();if(G.round&&G.round.firstHit==null)G.round.firstHit=G.round.t}if(b.hp<=0){if(G.round&&G.round.firstHit!=null&&G.round.bossDefeatT==null)G.round.bossDefeatT=G.round.t;killBoss(b)}}for(let n of [...G.nodes]){let d=def(n);if(d.type==='Boss')continue;let nearBoss=G.nodes.some(b=>def(b).type==='Boss'&&rectOverlap(n,b)),nearHazard=!nearBoss&&G.nodes.some(h=>h.id!==n.id&&def(h).hazard&&h.staffed&&rectOverlap(n,h)),delta=nearBoss?.08:nearHazard?.04:-.15,cap=nearBoss?1:.7;n.erosion=Math.max(0,Math.min(cap,n.erosion+delta));if(nearBoss&&n.erosion>=1)destroyNode(n.id,true)}for(let n of G.nodes.filter(n=>def(n).type==='Unit'&&!n.suspended))tickWorker(n);for(let n of G.nodes.filter(n=>def(n).type==='Source'&&!n.suspended))tickSource(n);for(let n of G.nodes.filter(n=>['Processor','Logic'].includes(def(n).type)&&!n.suspended))tickRecipe(n);cleanupEmptyResources();checkRoundConditions();checkMission();if(!G.hint50Shown&&(G.credits||0)>=50){G.hint50Shown=true;ariaHint('연구 승인으로 캠프를 영구적으로 개선할 수 있습니다.')}if(!drag&&!link&&!box&&!panDrag)renderAll();else{renderMissions();renderZones();renderFields()}}
function rectOverlap(n,b){let cx=b.x+87,cy=b.y+56;return n.x+174>=cx-b.radius&&n.x<=cx+b.radius&&n.y+112>=cy-b.radius&&n.y<=cy+b.radius}
function tickWorker(n){let d=def(n),cap=maxHp(n);if(n.hp>=cap)return;let food=incoming(n.id).map(x=>resolveResource(x.n.id)).filter(Boolean).find(x=>def(x).food&&x.count>0);if(food){food.count--;n.hp=Math.min(cap,n.hp+(def(food).heal||1)+up('food'));if(def(food).hazardFood)n.erosion=Math.min(.7,n.erosion+.15);toast(`${d.title}가 ${def(food).title}을 섭취해 체력을 회복했습니다.`)}}
function tickSource(n){let d=def(n),incRaw=incoming(n.id).map(x=>resolveNodeInfo(x.n.id)).filter(Boolean),ins=incRaw.map(x=>x.node),workers=incRaw.filter(x=>def(x.node).type==='Unit'&&x.node.hp>0),work=workers.length+ins.reduce((s,rn)=>s+(def(rn).type==='Buff'?(def(rn).production||0):0),0),seed=d.seedKey?ins.find(rn=>def(rn).key===d.seedKey&&rn.count>0):null,boost=d.boostKey?ins.some(rn=>def(rn).key===d.boostKey&&rn.count>0):false,weightRatio=workers.length?workers.reduce((s,x)=>s+(x.splitter?splitWeight():1),0)/workers.length:1;n.processing=false;n.staffed=workers.length>0&&(!d.seedKey||seed);work=Math.round(work*(1-n.erosion));if(work<=0||d.seedKey&&!seed)return;let r=sourceOutput(n.id,d.key);if(!r){let vr=$('#viewport').getBoundingClientRect(),rx=n.x+250,ry=n.y,right=(vr.width-G.pan.x)/G.pan.z,bottom=(vr.height-G.pan.y)/G.pan.z;if(rx+174>right){rx=n.x;ry=n.y+160}if(ry+112>bottom){rx=n.x-250;ry=n.y}r=spawn(resourceDef[d.key],rx,ry);G.wires.push({from:n.id,fp:0,to:r.id,tp:0,points:[]});renderAll();burstAt(r.x,r.y+42,'#ffcc00',40)}n.processing=true;n.progress+=(1-n.erosion)*weightRatio;let effTime=boost?Math.max(3,d.time-3):d.time;if(n.progress>=effTime){r.count+=work;if(seed)seed.count--;workers.forEach(x=>x.node.hp=Math.max(0,x.node.hp-1));n.progress=0}}
function refundRecipeInputs(n,inputSpec){for(let[k,v] of Object.entries(inputSpec)){let r=findResource(k);if(r)r.count+=v;else{let nr=spawn(resourceDef[k],n.x-220,n.y);nr.count=v}}}
function tickRecipe(n){let d=def(n),inputs={};for(let q of incoming(n.id)){let r=resolveResource(q.n.id);if(r)inputs[def(r).key]=r}if(n.processing){let cur=d.recipes[n.recipe];if(!cur||!Object.keys(cur.in).every(k=>inputs[k])){if(cur)refundRecipeInputs(n,cur.in);n.processing=false;n.recipe=-1;n.progress=0}}if(!n.processing){for(let i=0;i<d.recipes.length;i++){let rec=d.recipes[i],ok=Object.entries(rec.in).every(([k,v])=>inputs[k]&&inputs[k].count>=v);if(ok){Object.entries(rec.in).forEach(([k,v])=>inputs[k].count-=v);n.processing=true;if(n.recipe!==i)n.progress=0;n.recipe=i;break}}}if(n.processing){n.progress+=(1-n.erosion)*(1+up('proc'));if(n.progress>=d.time){let rec=d.recipes[n.recipe],out=sourceOutput(n.id,rec.out.key);if(!out){G.wires=G.wires.filter(w=>w.from!==n.id);out=spawn(resourceDef[rec.out.key],n.x+220,n.y);G.wires.push({from:n.id,fp:0,to:out.id,tp:0,points:[]})}out.count+=rec.out.n;n.processing=false;n.progress-=d.time}}}
function totalStars(){return Object.values(G.stars||{}).reduce((a,b)=>a+b,0)}
function maxHp(n){let base=def(n).type==='Unit'?Math.round(def(n).hp*(1+up('hp'))):def(n).hp;return base+(def(n).type==='Unit'&&totalStars()>=10?2:0)}
function splitWeight(){return totalStars()>=20?.6:.5}
function starConds(star){return star.conds||[star]}
function activeWorkerCount(){let ids=new Set();for(let n of G.nodes.filter(n=>['Source','Boss'].includes(def(n).type)))for(let x of incoming(n.id)){let rn=resolveNode(x.n.id);if(rn&&def(rn).type==='Unit'&&rn.hp>0)ids.add(rn.id)}return ids.size}
function starConditionLabel(star){return starConds(star).map(c=>{if(c.type==='time')return `${c.sec}초 안에 달성`;if(c.type==='hpAtClear')return `체력 ${c.n} 이상으로 달성`;if(c.type==='resourceAtClear')return `달성 시 ${D[c.key]?.title||c.key} ${c.min}개 이상 보유`;if(c.type==='keepMin')return `${D[c.key]?.title||c.key} ${c.min}개 이상 유지`;if(c.type==='maxWorkers')return `노동자 ${c.n}명 이하로`;if(c.type==='maxErosion')return `침식 ${Math.round(c.v*100)}%를 넘지 않고`;if(c.type==='noPurchase')return `배급 요청 없이`;if(c.type==='bossBurst')return `첫 타격 후 ${c.sec}초 안에 진압`;return''}).join(' · ')}
function starFailReason(star){let c=starConds(star).find(c=>['keepMin','maxWorkers','maxErosion','noPurchase'].includes(c.type));if(!c)return'조건을 달성할 수 없게 되었습니다.';if(c.type==='keepMin')return `${D[c.key]?.title||c.key}이(가) ${c.min}개 미만이 되었습니다.`;if(c.type==='maxWorkers')return `노동자가 ${c.n}명을 초과해 연결되었습니다.`;if(c.type==='maxErosion')return `침식이 ${Math.round(c.v*100)}%를 넘었습니다.`;return '배급 요청으로 노드를 구매했습니다.'}
function failRoundStar(si,star){if(G.round.failed.includes(si))return;G.round.failed.push(si);toast(`${'★'.repeat(si+2)} 실패 — ${starFailReason(star)}`,'error');renderMissions()}
function checkRoundConditions(){let c=chapters[G.chapter];if(!c||!c.stars||!G.round||G.cleared)return;let overlaysOpen=!$('#dialogue').classList.contains('hidden')||!$('#requisition').classList.contains('hidden')||!$('#tribute').classList.contains('hidden')||!$('#functionNodes').classList.contains('hidden')||!$('#packOverlay').classList.contains('hidden');if(!overlaysOpen)G.round.t++;let maxE=G.nodes.length?Math.max(0,...G.nodes.map(x=>x.erosion||0)):0,workers=activeWorkerCount();c.stars.forEach((star,si)=>{if(G.round.failed.includes(si))return;for(let cond of starConds(star)){if(cond.type==='keepMin'&&resourceTotal(cond.key)<cond.min){failRoundStar(si,star);break}if(cond.type==='maxWorkers'&&workers>cond.n){failRoundStar(si,star);break}if(cond.type==='maxErosion'&&maxE>cond.v){failRoundStar(si,star);break}}})}
function markPurchase(){let c=chapters[G.chapter];if(!c||!c.stars||!G.round)return;c.stars.forEach((star,si)=>{if(!G.round.failed.includes(si)&&starConds(star).some(cd=>cd.type==='noPurchase'))failRoundStar(si,star)})}
function evalStarSnapshot(star){for(let cond of starConds(star)){if(cond.type==='time'&&G.round.t>cond.sec)return false;if(cond.type==='hpAtClear'){let m=node(G.main);if(!m||m.hp<cond.n)return false}if(cond.type==='resourceAtClear'&&resourceTotal(cond.key)<cond.min)return false;if(cond.type==='bossBurst'){if(G.round.firstHit==null)return false;let endT=G.round.bossDefeatT??G.round.t;if(endT-G.round.firstHit>cond.sec)return false}}return true}
function awardBonusCard(c){let kinds=Object.keys(funcNodes),kind=kinds[Math.floor(Math.random()*kinds.length)],last=c.cards[c.cards.length-1]||['',100,400];c.cards.push([kind,last[1]+250,last[2],`▣ 우수 등급 보너스: ${D[kind].title}가 추가로 지급되었습니다.`])}
function checkStarMilestones(){G.starMilestones=G.starMilestones||{};let total=totalStars(),milestones=[[10,'노동자 최대 체력이 10 → 12로 상향되었습니다.'],[20,'보급 분배기 효율이 0.5 → 0.6으로 상향되었습니다.'],[30,'보너스 CR 50이 지급되었습니다.'],[39,'하트웰 인턴 평가 "우수" 등급을 획득했습니다.']];for(let[th,msg] of milestones){if(total>=th&&!G.starMilestones[th]){G.starMilestones[th]=true;if(th===30){G.credits=(G.credits||0)+50;logCr(50)}toast(`누적 별 ${th}개 달성 — ${msg}`,'success')}}}
function gradeRound(c,onContinue){let grade=1;if(c.stars){for(let si=0;si<c.stars.length;si++){if(grade!==si+1)break;let star=c.stars[si];if(!G.round.failed.includes(si)&&evalStarSnapshot(star))grade=si+2}}G.stars=G.stars||{};let prevBest=G.stars[G.chapter]||0;if(grade>prevBest){G.stars[G.chapter]=grade;if(grade===2){G.credits=(G.credits||0)+10;logCr(10)}if(grade===3){G.credits=(G.credits||0)+40;logCr(40);awardBonusCard(c)}checkStarMilestones()}showRoundResult(c,grade,onContinue)}
function checkpointRoundStart(){if(slot<0||!G)return;localStorage.setItem(saveKey(slot)+'_roundstart',JSON.stringify(G))}
function retryRound(){if(slot<0)return;let raw=localStorage.getItem(saveKey(slot)+'_roundstart');if(!raw){toast('다시 시작할 저장 지점이 없습니다.','error');return}G=JSON.parse(raw);G.paused=false;G.gameOver=false;startPlay(false);toast('라운드를 다시 시작합니다.','silent')}
function showRoundResult(c,grade,onContinue){pendingResultContinue=onContinue||null;$('#resultRoundTitle').textContent=c.title;for(let i=1;i<=3;i++)$(`#resultStar${i}`).classList.toggle('filled',i<=grade);let lines=[];if(c.stars)c.stars.forEach((star,si)=>{let failed=G.round.failed.includes(si),ok=si+2<=grade;lines.push(`<div class="result-star-line ${ok?'ok':failed?'fail':'miss'}">${'★'.repeat(si+2)} ${starConditionLabel(star)} — ${ok?'달성':'실패'}</div>`)});$('#resultStarLines').innerHTML=lines.join('');let missedHint='';if(c.stars)for(let si=0;si<c.stars.length;si++){if(si+2>grade&&c.stars[si].hint){missedHint=`힌트: ${c.stars[si].hint}`;break}}$('#resultHint').textContent=missedHint;$('#resultHint').classList.toggle('hidden',!missedHint);overlay('roundResult',true);sfx.success()}
function checkMission(){let c=chapters[G.chapter];if(!c||G.cleared||c.finalChoice)return;let v=c.creditGoal?(G.credits||0)-(G.round.creditsAtStart||0):(c.key?resourceTotal(c.key):0),goal=c.creditGoal||c.goal;if(v>=goal&&(!c.requireNoBoss||!G.nodes.some(n=>def(n).type==='Boss'))){G.cleared=true;gradeRound(c);checkpoint()}}
function openStarterPack(done){packMode='starter';packDone=done;overlay('packOverlay',true);$('#packTitle').textContent='기본 제공 팩';$('#packBoxText').textContent='클릭하여\n씨앗 5개 수령';$('#cardReveal').classList.add('hidden');$('#packBox').classList.remove('hidden','explode');$('#packBox').style.display='grid'}
function openPack(){let c=chapters[G.chapter];if(!c)return;packMode='reward';G.packIndex=0;overlay('packOverlay',true);$('#packTitle').textContent=`${G.chapter+1}라운드 보상 팩`;$('#packBoxText').textContent=`클릭하여\n카드 ${c.cards.length}장 뽑기`;$('#cardReveal').classList.add('hidden');$('#packBox').classList.remove('hidden','explode');$('#packBox').style.display='grid'}
function showCardReveal(kind,msg){let d=D[kind];$('#cardReveal').classList.remove('hidden');$('#cardReveal').style.setProperty('--accent',C[d.type]);$('#cardGlyph').innerHTML=iconHtml(kind);$('#cardType').textContent=typeLabel[d.type]||d.type;$('#cardName').textContent=d.title;$('#cardMessage').textContent=msg}
function drawCard(){if(packMode==='starter'){if(G.starterOpened)return;G.starterOpened=true;spawn('seed',100,360,{count:5});showCardReveal('seed','땅의 자원 입력 포트에 연결하세요.');$('#packBox').classList.add('explode');burstScreen(innerWidth/2,innerHeight/2,C.Resource,40);sfx.packOpen();renderAll();setTimeout(()=>{overlay('packOverlay',false);packMode='reward';let done=packDone;packDone=null;done?.()},900);return}let c=chapters[G.chapter],entry=c.cards[G.packIndex];if(!entry)return;let[k,x,y,msg]=entry,n=spawn(k,x,y);if(k==='seed')n.count=5;G.packIndex++;showCardReveal(k,msg);$('#packBox').classList.remove('shake');void $('#packBox').offsetWidth;$('#packBox').classList.add('shake');burstScreen(innerWidth/2,innerHeight/2,C[D[k].type],30);sfx.shake();let left=c.cards.length-G.packIndex;if(left)$('#packBoxText').textContent=`${left}장 남음!`;else{$('#packBox').classList.add('explode');sfx.packOpen();setTimeout(finishPack,900)}renderAll()}
function finishPack(){overlay('packOverlay',false);let c=chapters[G.chapter];G.chapter++;G.cleared=false;G.round={t:0,failed:[],firstHit:null,bossDefeatT:null,creditsAtStart:G.credits||0};let done=()=>{if(c.boss){let pos=c.bossPos||{x:1700,y:1050},b=spawn(c.bossKind||'boss',pos.x,pos.y);b.locked=true;focusNode(b);toast('캠프 복합 위기가 발생했습니다!','alarm');G.paused=true;overlay('bossTutorial',true)}if(G.chapter>=chapters.length)toast(c.complete,'success');else ariaHint('새 라운드 목표: '+chapters[G.chapter].desc.replace(/^목표:\s*/,''));checkpoint();checkpointRoundStart();renderAll()};c.story?playDialogue(c.story,done):done()}
function playDialogue(lines,done){dialogue={lines,i:0,done,typing:false,full:''};overlay('dialogue',true);showLine()}
function showLine(){let [who,text,visual]=dialogue.lines[dialogue.i];dialogue.full=text;dialogue.typing=true;$('#speaker').textContent=who;$('#dialogueText').textContent='';let card=historyVisuals[visual],view=$('#historyVisual'),changed=visual!==dialogue.lastVisual;view.classList.toggle('hidden',!card);if(card){$('#historyYear').textContent=card[0];$('#historyIcon').innerHTML=historyImages[visual]?`<img src="${historyImages[visual]}" alt="${card[2]}">`:card[1];$('#historyTitle').textContent=card[2];$('#historyCaption').textContent=card[3];if(changed){view.classList.remove('pop');void view.offsetWidth;view.classList.add('pop')}}dialogue.lastVisual=card?visual:null;let i=0;clearInterval(dialogue.timer);dialogue.timer=setInterval(()=>{i++;$('#dialogueText').textContent=text.slice(0,i);if(text[i-1]&&text[i-1].trim())sfx.type();if(i>=text.length){clearInterval(dialogue.timer);dialogue.typing=false}},25)}
function advanceDialogue(){if(!dialogue)return;if(dialogue.typing){clearInterval(dialogue.timer);$('#dialogueText').textContent=dialogue.full;dialogue.typing=false;return}dialogue.i++;if(dialogue.i>=dialogue.lines.length){let d=dialogue.done;dialogue=null;overlay('dialogue',false);d?.()}else showLine()}
