const gradeScale=[{g:'S',r:.9,word:'EXCELLENT',msg:'탁월 — 모든 복원 절차를 최적의 효율로 완수했습니다. 하트웰 복원국 정규직 전환 우선 심사 대상으로 추천됩니다.'},{g:'A',r:.75,word:'SUPERIOR',msg:'우수 — 안정적인 운영 능력을 입증했습니다. 다음 사이클의 핵심 인력으로 배치됩니다.'},{g:'B',r:.55,word:'STANDARD',msg:'양호 — 기본 복원 절차를 충실히 수행했습니다. 생산 효율 개선 과제가 권고됩니다.'},{g:'C',r:0,word:'PROVISIONAL',msg:'보완 필요 — 목표는 달성했으나 효율 기준에 미달했습니다. 다음 사이클에서 재평가가 진행됩니다.'}];
function showFinalGrade(onDone){let last=chapters.findIndex(c=>c.finalChoice),rounds=chapters.slice(0,last+1),per=rounds.map((c,i)=>Math.min(G.stars?.[i]||0,(c.stars?.length||0)+1)),stars=per.reduce((a,b)=>a+b,0),max=rounds.reduce((s,c)=>s+(c.stars?.length||0)+1,0),rank=gradeScale.find(x=>stars/max>=x.r);G.finalGrade={grade:rank.g,stars,max};checkpoint();let p=$('#finalGrade .grade-panel');p.dataset.grade=rank.g;p.classList.remove('stamped');$('#gradeLetter').textContent=rank.g;$('#gradeWord').textContent=rank.word;$('#gradeComment').textContent=rank.msg;$('#gradeMax').textContent=max;$('#gradeStars').textContent='0';$('#gradeFill').style.width='0%';document.querySelectorAll('#finalGrade .grade-tick').forEach(t=>{let s=gradeScale.find(x=>x.g===t.dataset.g);t.style.left=s.r*100+'%';t.classList.toggle('reached',stars/max>=s.r)});$('#gradeRounds').innerHTML=per.map((s,i)=>{let cap=(rounds[i].stars?.length||0)+1;return`<div class="gr-cell${s>=cap?' perfect':''}" style="--i:${i}"><small>${String(i+1).padStart(2,'0')}</small><span>${Array.from({length:cap},(_,k)=>`<i class="${k<s?'on':''}"></i>`).join('')}</span></div>`}).join('');$('#gradeContinueBtn').onclick=()=>{overlay('finalGrade',false);onDone?.()};overlay('finalGrade',true);let t0=null,dur=1300,delay=900;function step(t){if(t0===null)t0=t;let k=Math.min(1,Math.max(0,(t-t0-delay)/dur)),e=1-Math.pow(1-k,3);$('#gradeStars').textContent=Math.round(stars*e);$('#gradeFill').style.width=(stars/max*100*e)+'%';if(k<1)requestAnimationFrame(step);else{p.classList.add('stamped');sfx.victory()}}requestAnimationFrame(step)}
function showEnding(){G.cleared=true;$('#endingTitle').textContent='1차 평가 완료';$('#endingDesc').textContent=`위기를 진압하고 캠프의 안정을 되찾았습니다. 이 성과는 인턴 평가 기록에 반영되었습니다.\n\n제1캠프 복원 프로그램 1차 실습 시뮬레이션이 여기서 마무리됩니다. 캠프의 재건 작업은 계속되며, 다음 사이클(자원 심화 편)로 이어집니다.\n\n실습에 참여해 주셔서 감사합니다.`;overlay('endingScreen',true);sfx.victory();G.paused=false;checkpoint();renderAll()}
function continueAfterEnding(){overlay('endingScreen',false);openPack()}
function gameOver(){G.gameOver=true;clearInterval(timer);overlay('gameOver',true);sfx.gameOver()}function destroyNode(id,fx){let n=node(id);if(!n)return;G.wires=G.wires.filter(w=>w.from!==id&&w.to!==id);G.nodes=G.nodes.filter(x=>x.id!==id);if(fx)burstAt(n.x+87,n.y+55,'#34152e',25)}
function cleanupEmptyResources(){for(let n of [...G.nodes]){if(!['Resource','Equipment'].includes(def(n).type)||n.count>0)continue;let inUse=G.wires.some(w=>{let other=w.to===n.id?node(w.from):w.from===n.id?node(w.to):null;return other&&['Source','Processor','Logic'].includes(def(other).type)});if(!inUse)destroyNode(n.id,false)}}
function burstAt(x,y,c,n){let r=$('#viewport').getBoundingClientRect();burstScreen(r.left+G.pan.x+x*G.pan.z,r.top+G.pan.y+y*G.pan.z,c,n)}function burstPort(id,p,c){let e=$(`.node[data-node="${id}"] .port.in[data-port="${p}"]`),r=e.getBoundingClientRect();burstScreen(r.left+8,r.top+8,c,18)}function burstScreen(x,y,c,n){for(let i=0;i<n;i++){let p=document.createElement('i'),a=Math.random()*Math.PI*2,d=25+Math.random()*65;p.className='particle';p.style.cssText=`left:${x}px;top:${y}px;--c:${c};--x:${Math.cos(a)*d}px;--y:${Math.sin(a)*d}px`;$('#particles').append(p);setTimeout(()=>p.remove(),700)}}
function toast(t,type){$('#toast').textContent=t;$('#toast').style.opacity=1;clearTimeout(toastT);toastT=setTimeout(()=>$('#toast').style.opacity=0,1800);if(type==='error')sfx.error();else if(type==='success')sfx.success();else if(type==='alarm')sfx.alarm();else if(type!=='silent')sfx.connect()}
let ariaHintTimer=null,ariaHintFade=null;
function ariaHint(t,ms){clearTimeout(ariaHintTimer);clearTimeout(ariaHintFade);$('#ariaHintText').textContent=t;$('#ariaHint').classList.remove('hidden');requestAnimationFrame(()=>$('#ariaHint').classList.add('show'));ariaHintTimer=setTimeout(()=>{$('#ariaHint').classList.remove('show');ariaHintFade=setTimeout(()=>$('#ariaHint').classList.add('hidden'),300)},ms||5000)}function focusNode(n){let r=$('#viewport').getBoundingClientRect();G.pan.x=r.width/2-(n.x+87)*G.pan.z;G.pan.y=r.height/2-(n.y+56)*G.pan.z;applyView()}function focusMain(){let n=node(G.main);if(n)focusNode(n)}
function tributeResource(key,amount){let rate=tributeRates[key],total=resourceTotal(key);if(!rate||total<=0)return;amount=Math.max(1,Math.min(Math.round(amount||total),total));let cr=Math.floor(amount*rate*(1+up('tribute'))),kind=Object.keys(D).find(k=>D[k].key===key&&['Resource','Equipment'].includes(D[k].type)),remain=amount;for(let r of resources(key)){if(remain<=0)break;let take=Math.min(r.count,remain);r.count-=take;remain-=take}cleanupEmptyResources();G.credits=(G.credits||0)+cr;G.tributeGuided=true;logCr(cr);toast(`${D[kind].title} ${amount}개 상납 완료 · CR ${cr} 획득`,'success');checkMission();renderShop();renderAll();checkpoint()}
function renderTribute(){let grid=$('#tributeGrid'),active=new Set();for(let[key,rate] of Object.entries(tributeRates)){let total=resourceTotal(key);if(total<=0)continue;active.add(key);let kind=Object.keys(D).find(k=>D[k].key===key&&['Resource','Equipment'].includes(D[k].type)),row=grid.querySelector(`.tribute-row[data-tribute-key="${key}"]`);if(!row){row=document.createElement('div');row.className='tribute-row';row.dataset.tributeKey=key;row.innerHTML=`<span class="shop-icon">${iconHtml(kind)}</span><div class="tribute-info"><b>${D[kind].title}</b><small></small></div><div class="tribute-qty"><button type="button" class="qty-btn" data-step="-1">−</button><input type="number" class="qty-input" min="1"><button type="button" class="qty-btn" data-step="1">+</button></div><button type="button" class="tribute-confirm">상납 <b class="tribute-cr"></b></button>`;grid.appendChild(row)}row.dataset.rate=rate;row.dataset.max=total;let goalKey=chapters[G.chapter]?.key,warn=goalKey===key?` · 현재 목표 자원입니다 (${total} / ${chapters[G.chapter].goal})`:'';row.querySelector('.tribute-info small').textContent=`보유 ${total}${warn}`;let input=row.querySelector('.qty-input'),focused=document.activeElement===input,qty=Math.max(1,Math.min(+input.value||total,total));input.max=total;if(!focused)input.value=qty;row.querySelector('.tribute-cr').textContent=`CR ${Math.floor(qty*rate*(1+up('tribute')))}`}grid.querySelectorAll('.tribute-row').forEach(row=>{if(!active.has(row.dataset.tributeKey))row.remove()});if(!active.size)grid.innerHTML='<p class="shop-empty">상납 가능한 자원이 없습니다.</p>';else grid.querySelector('.shop-empty')?.remove()}
function tributeSetQty(row,val){let max=+row.dataset.max,rate=+row.dataset.rate,input=row.querySelector('.qty-input'),v=Math.max(1,Math.min(Math.round(val),max));input.value=v;row.querySelector('.tribute-cr').textContent=`CR ${Math.floor(v*rate*(1+up('tribute')))}`}
const funcNodes={splitter:{cost:15,limit:4,unlock:1},buff:{cost:20,limit:3,unlock:1},add:{cost:20,limit:2,unlock:2},multiply:{cost:35,limit:1,unlock:2},number3:{cost:25,limit:2,unlock:4},portal:{cost:30,limit:2,unlock:4},multiply2:{cost:40,limit:1,unlock:4},if5:{cost:35,limit:1,unlock:8}};
