function decorateFuncDescs(){document.querySelectorAll('#functionNodes [data-func]').forEach(b=>{let kind=b.dataset.func,d=D[kind],cfg=funcNodes[kind];if(!d||b.querySelector('.shop-desc'))return;let io=t=>t.length?t.map(x=>typeLabel[x]||x).join(' + '):'없음',el=document.createElement('span');el.className='shop-desc';el.style.setProperty('--desc-c',C[d.type]||C.Splitter);el.innerHTML=`<span class="sd-head"><small>${typeLabel[d.type]||d.type}</small><b>${d.title}</b><em>입력 ${io(d.ins)} → 출력 ${io(d.outs)}</em></span><span class="sd-body">${d.desc}</span><span class="sd-meta">CR ${cfg.cost} · 최대 ${cfg.limit}개 · ${cfg.unlock}라운드 클리어 후 해금</span>`;b.append(el)})}
function renderShop(){let cr=G.credits||0;$('#reqCredits').textContent=`CR ${cr}`;$$('#requisition [data-buy]').forEach(b=>{let kind=b.dataset.buy,unlock=requisitionUnlocks[kind],unlocked=unlock===undefined||G.chapter>=unlock,limitEl=b.querySelector('.shop-limit'),cost=priceFor(kind)??+b.dataset.cost,priceEl=b.querySelector('.shop-price');if(priceEl&&priceFor(kind)!=null)priceEl.textContent=`CR ${cost}`;b.classList.toggle('locked-item',!unlocked);b.disabled=!unlocked||cr<cost;if(limitEl)limitEl.textContent=unlocked?'':`${unlock}라운드 클리어 해금`});renderTribute();$('#funcCredits').textContent=`CR ${cr}`;$$('#functionNodes [data-func]').forEach(b=>{let kind=b.dataset.func,cfg=funcNodes[kind],count=G.nodes.filter(n=>n.kind===kind).length,unlocked=G.chapter>=cfg.unlock,limitEl=b.querySelector('.shop-limit');b.classList.toggle('locked-item',!unlocked);b.disabled=!unlocked||count>=cfg.limit||cr<cfg.cost;if(limitEl)limitEl.textContent=unlocked?`${count} / ${cfg.limit}`:`${cfg.unlock}라운드 클리어 해금`});renderResearch()}
function tooltipDesc(n,d){let extra='';if(['Processor','Logic'].includes(d.type)&&d.time&&up('proc')>0)extra+=`\n(소요: ${d.time}초 → ${(d.time/(1+up('proc'))).toFixed(1)}초, 가공 속도 Lv${G.upgrades.proc})`;if(d.type==='Unit'&&up('hp')>0)extra+=`\n(체력 상한: ${d.hp} → ${maxHp(n)}, 노동력 체력 Lv${G.upgrades.hp})`;if(d.food&&up('food')>0)extra+=`\n(회복량: ${d.heal||1} → ${(d.heal||1)+up('food')}, 섭취 효율 Lv${G.upgrades.food})`;return d.desc+extra}
function formatUpgradeVal(k,lvl){let v=upgradeDefs[k].vals[lvl];if(!v)return'-';return k==='food'?`+${v}`:`+${Math.round(v*100)}%`}
function renderResearch(){let cr=G.credits||0;$('#researchCredits').textContent=`CR ${cr}`;$('#researchGrid').innerHTML=Object.entries(upgradeDefs).map(([k,def])=>{let lvl=G.upgrades?.[k]||0,maxed=lvl>=3,pips=[0,1,2].map(i=>`<i class="${i<lvl?'filled':''}"></i>`).join(''),curVal=formatUpgradeVal(k,lvl),nextVal=maxed?'-':formatUpgradeVal(k,lvl+1),cost=maxed?null:def.cost[lvl],unlockAt=maxed?null:def.unlock[lvl],locked=!maxed&&G.chapter<unlockAt,breakeven=k==='tribute'&&!maxed?`<small>본전까지 CR ${Math.round(cost/(def.vals[lvl+1]-def.vals[lvl]))}</small>`:'',btnLabel=maxed?'MAX':locked?`🔒 ${unlockAt}라운드 클리어`:`CR ${cost}`,disabled=maxed||locked||cr<cost;return `<div class="research-row"><div class="research-info"><b>${def.name}</b><span class="research-pips">${pips}</span><small>현재 ${curVal} → 다음 ${nextVal}</small>${breakeven}</div><button class="research-buy" data-upgrade="${k}" ${disabled?'disabled':''}>${btnLabel}</button></div>`}).join('')}
function buyUpgrade(k){let udef=upgradeDefs[k],lvl=G.upgrades?.[k]||0;if(lvl>=3)return;if(G.chapter<udef.unlock[lvl]){toast('아직 해금되지 않았습니다.','error');return}let cost=udef.cost[lvl];if((G.credits||0)<cost){toast('크레딧이 부족합니다.','error');return}G.credits-=cost;G.upgrades=G.upgrades||{};G.upgrades[k]=lvl+1;toast(`${udef.name} Lv${lvl+1} 연구 완료`,'success');sfx.success();for(let n of G.nodes.filter(n=>k==='hp'||k==='food'?def(n).type==='Unit':k==='proc'?['Processor','Logic'].includes(def(n).type):false))burstAt(n.x+87,n.y+55,C[def(n).type],16);renderAll();renderResearch();checkpoint()}
function buyNode(kind,cost){cost=priceFor(kind)??cost;if((G.credits||0)<cost){toast('크레딧이 부족합니다.','error');return}G.credits-=cost;G.bought=G.bought||{};if(priceFor(kind)!=null)G.bought[kind]=(G.bought[kind]||0)+1;let i=G.nodes.length,n=spawn(kind,180+(i%3)*230,420+Math.floor(i/3)*150);if(kind==='seed')n.count=5;overlay('requisition',false);toast(`${D[kind].title} 배급 승인`,'success');markPurchase();renderAll();checkpoint()}
function buyFuncNode(kind){let cfg=funcNodes[kind];if(!cfg||G.chapter<cfg.unlock){toast('아직 해금되지 않았습니다.','error');return}let count=G.nodes.filter(n=>n.kind===kind).length;if(count>=cfg.limit){toast('설치 개수 제한에 도달했습니다.','error');return}if((G.credits||0)<cfg.cost){toast('크레딧이 부족합니다.','error');return}G.credits-=cfg.cost;let i=G.nodes.length;spawn(kind,180+(i%3)*230,420+Math.floor(i/3)*150);overlay('functionNodes',false);toast(`${D[kind].title} 설치 완료`,'success');markPurchase();renderAll();checkpoint()}
function copy(){let ids=G.selected.filter(id=>{let t=def(node(id)).type;return!['Unit','Boss','Resource','Equipment'].includes(t)});clip=ids.map(id=>{let n=node(id);return{kind:n.kind,x:n.x,y:n.y}});clipW=G.wires.filter(w=>ids.includes(w.from)&&ids.includes(w.to)).map(w=>({...w,fi:ids.indexOf(w.from),ti:ids.indexOf(w.to)}));pasteN=0}
