function doPaste(cost){pasteN++;G.credits=(G.credits||0)-cost;let made=clip.map(q=>spawn(q.kind,q.x+30*pasteN,q.y+30*pasteN,{copy:true}));clipW.forEach(w=>G.wires.push({from:made[w.fi].id,fp:w.fp,to:made[w.ti].id,tp:w.tp,points:[]}));G.selected=made.map(n=>n.id);toast(`노드 ${made.length}개 복제 완료 · CR ${cost} 지불`,'success');renderAll();checkpoint()}
